// M6.5 Factory Analytics performance measurement (docs/mach-next/M6_5_TESTING.md, section "Budgets").
//
//   node scripts/analytics-measure.mjs --mode proof            the proof page on the simulated fixture (UI only)
//   node scripts/analytics-measure.mjs --mode live [--project large|medium|<dir>] [--reuse]
//        mach-observer (go build) on a project generated by `mach-synth --analytics` (default: large,
//        330 cells, 240,000 events), measured cold and warm, idle and under `mach-synth --append`,
//        and the Shell's #analytics over it once a live provider is mounted (else the UI steps say so).
// Options: --out <dir> (default <os tmpdir>/mach-analytics-measure), --runs <n> (5), --headed,
//          --append-rate <events/s> (200), --append-seconds <s> (15), --build (rebuild the tools),
//          --compare-baseline <mach-observer binary> (live only): after the working tree's observer, run
//          the same observer measurements (rebuild, restart, queries, idle, append) with that binary on an
//          identical copy of the project, and print its figures in a second column. Build the binary
//          yourself, e.g. from b37c036: `git worktree add /tmp/b b37c036 && cd /tmp/b/apps/observer &&
//          go build -o /tmp/mach-observer-b37c036 ./cmd/mach-observer`. Routes or parameters the
//          baseline does not serve are reported as such, never as a time.
//
// Ports: the dev server 4430 and relay 4439 (shared with the e2e suite), the observer 4435. Stops what it
// started. Each step that cannot run yet reports "not measurable yet: <why>"; the run never fails on it.
// Prints one table: measure, value, budget, pass/fail.
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import os, { tmpdir } from "node:os";
import { join } from "node:path";
import {
  AREAS,
  apiGet,
  apiSession,
  buildTools,
  chromium,
  DEV_ORIGIN,
  ensureStack,
  log,
  makeProject,
  OBSERVER_PORTS,
  sleep,
  startAppender,
  startObserver,
  stopOwn,
  waitCaughtUp,
} from "../e2e/analytics-lib.mjs";
import { distribution, heapAfterGc, machineFacts } from "./timeline-lib.mjs";

const argv = process.argv.slice(2);
const opt = (name, fallback) => {
  const i = argv.indexOf(`--${name}`);
  return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : fallback;
};
const MODE = opt("mode", "proof");
const BASELINE = opt("compare-baseline", null);
if (BASELINE && !existsSync(BASELINE)) {
  console.error(`--compare-baseline: no such file ${BASELINE}`);
  process.exit(2);
}
const RUNS = Number(opt("runs", 5));
const out = opt("out", join(tmpdir(), "mach-analytics-measure"));
mkdirSync(out, { recursive: true });

/**
 * Budgets. UI figures follow the Timeline's (M6_3_DESIGN.md section 8: first paint 1.5 s, workspace
 * switch 300 ms, 60 MB heap) and what the proof page measures today; API and observer figures are
 * proposed from the 240,000-event project. `ms` budgets are medians unless named p95.
 */
const BUDGET = {
  "ui.initial.median": 1500,
  "ui.area.median": 300,
  "ui.window.median": 300,
  "ui.filter.median": 300,
  "ui.brush.median": 200,
  "ui.hover.median": 50,
  "ui.compare.median": 500,
  "ui.heapDeltaMB": 60,
  "api.cold.max": 1000,
  "api.warm.median": 50,
  "api.warm.p95": 150,
  "api.compare.median": 100,
  "observer.idle.cpuPct": 2,
  "observer.idle.rssMB": 450,
  "observer.append.cpuPct": 50,
  "observer.append.cpuMsPerEvent": 1,
  "observer.append.lagMs": 2000,
  "observer.rebuild.ms": 60000,
  "observer.restart.ms": 10000,
};

const report = { generated: new Date().toISOString(), mode: MODE, machine: { ...machineFacts(), loadAverageAtStart: os.loadavg().map((x) => Math.round(x * 10) / 10) }, budget: BUDGET, steps: {}, results: {} };
/** Where `put` and `step` write: the working tree's observer, then (with --compare-baseline) the baseline's. */
let sink = report;
const put = (key, value) => (sink.results[key] = value);

async function step(name, fn) {
  const t0 = Date.now();
  try {
    sink.steps[name] = { ok: true, ...(await fn()), tookMs: Date.now() - t0 };
    log("measured", name, sink === report ? "" : "(baseline)");
  } catch (error) {
    sink.steps[name] = { ok: false, notMeasurable: String(error?.message ?? error).split("\n")[0].slice(0, 240) };
    log("not measurable yet:", name, sink === report ? "" : "(baseline)", "-", sink.steps[name].notMeasurable);
  }
}

// ------------------------------------------------------------ processes: CPU and RSS from ps

function psSample(pid) {
  const r = spawnSync("ps", ["-o", "time=,rss=", "-p", String(pid)], { encoding: "utf8" });
  const [time, rss] = r.stdout.trim().split(/\s+/);
  if (!time) return null;
  const parts = time.split(":").map(Number);
  const cpuS = parts.length === 3 ? parts[0] * 3600 + parts[1] * 60 + parts[2] : parts[0] * 60 + parts[1];
  return { cpuS, rssMB: Math.round(Number(rss) / 1024) };
}
async function cpuOver(pid, ms) {
  const a = psSample(pid);
  const t = Date.now();
  const rss = [];
  while (Date.now() - t < ms) {
    await sleep(500);
    rss.push(psSample(pid)?.rssMB ?? 0);
  }
  const b = psSample(pid);
  return { cpuPct: Math.round(((b.cpuS - a.cpuS) / ((Date.now() - t) / 1000)) * 1000) / 10, cpuMs: Math.round((b.cpuS - a.cpuS) * 1000), rssMB: Math.max(...rss) };
}

// ------------------------------------------------------------ the observer and its API

let observer = null;
let cookie = null;
let project = null;
/** The binary and project copy the observer steps use now. */
let subject = { binary: undefined, dir: null };

const QUERIES = (end) => {
  const week = `from_ms=${end - 7 * 864e5}&to_ms=${end}`;
  return {
    "metrics all": "/api/v1/analytics/metrics",
    "metrics windowed": `/api/v1/analytics/metrics?${week}`,
    "metrics grouped": "/api/v1/analytics/metrics?ids=C1,W3,K1&group_by=station,risk",
    "metrics distribution": "/api/v1/analytics/metrics?ids=C1,W3,T3&distribution=1&bucket=day",
    "metrics last_runs": "/api/v1/analytics/metrics?ids=Q2,Q1&last_runs=20",
    // Through a playhead half a week before the end (the observer's as_of_ms: nothing recorded later counts).
    "metrics as_of": `/api/v1/analytics/metrics?as_of_ms=${Math.round(end - 3.5 * 864e5)}`,
    flow: "/api/v1/analytics/flow",
    "flow windowed": `/api/v1/analytics/flow?${week}`,
    contributors: "/api/v1/analytics/contributors?metric=C1&group=station:build&limit=200",
    runs: "/api/v1/analytics/runs",
    insights: "/api/v1/analytics/insights",
  };
};

async function liveSetup() {
  if (argv.includes("--build")) for (const n of buildTools()) log(n);
  await ensureStack({ tools: true });
  const p = opt("project", "large");
  const gen0 = Date.now();
  project = ["tiny", "medium", "large", "one"].includes(p) ? makeProject(p, { reuse: argv.includes("--reuse"), name: `measure-${p}` }) : { dir: p, summary: null };
  report.workload = { project: p, generateMs: Date.now() - gen0, events: project.summary?.events ?? null, cells: project.summary?.cells ?? null };
  subject = { binary: undefined, dir: project.dir };
  // The baseline measures an identical copy, taken before anything is appended to the original.
  if (BASELINE) {
    const copy = `${project.dir}-baseline`;
    rmSync(copy, { recursive: true, force: true });
    const r = spawnSync("rsync", ["-a", "--exclude", ".factory/local/observer", `${project.dir}/`, `${copy}/`], { encoding: "utf8" });
    if (r.status !== 0) throw new Error(`copying the project for the baseline failed: ${r.stderr}`);
    report.baseline = { binary: BASELINE, dir: copy, results: {}, steps: {} };
  }
}

async function measureRebuild() {
  await step("observer rebuild and restart", async () => {
    rmSync(join(subject.dir, ".factory", "local", "observer"), { recursive: true, force: true });
    observer = await startObserver(subject.dir, OBSERVER_PORTS.measure, { timeoutMs: 600000, binary: subject.binary });
    cookie = await apiSession(observer);
    await waitCaughtUp(observer, cookie);
    const rebuild = Date.now() - observer.started;
    await observer.stop();
    await sleep(500);
    observer = await startObserver(subject.dir, OBSERVER_PORTS.measure, { timeoutMs: 600000, binary: subject.binary });
    cookie = await apiSession(observer);
    await waitCaughtUp(observer, cookie);
    const restart = Date.now() - observer.started;
    put("observer.rebuild.ms", rebuild);
    put("observer.restart.ms", restart);
    return { rebuildMs: rebuild, restartMs: restart };
  });
}

async function measureApi() {
  await step("api latencies", async () => {
    const head = await apiGet(observer, cookie, "/api/v1/analytics/metrics?ids=T1");
    const end = head.data?.history?.to_ms ?? head.data?.window?.effective_to_ms ?? project.summary?.end_ms ?? Date.now();
    const cursor = head.data?.cursor;
    const rows = {};
    const cold = [];
    const warm = [];
    for (const [name, path] of Object.entries(QUERIES(end))) {
      const first = await apiGet(observer, cookie, path);
      if (first.status !== 200) {
        rows[name] = { notServed: `${first.status} ${first.body?.error?.message ?? ""}`.trim() };
        continue;
      }
      const ws = [];
      for (let i = 0; i < RUNS; i++) ws.push((await apiGet(observer, cookie, path)).ms);
      const atPath = `${path}${path.includes("?") ? "&" : "?"}at=${encodeURIComponent(cursor)}`;
      const at = [];
      for (let i = 0; i < RUNS && cursor; i++) {
        const g = await apiGet(observer, cookie, atPath);
        if (g.status !== 200) break;
        at.push(g.ms);
      }
      rows[name] = { status: first.status, coldMs: Math.round(first.ms), warm: distribution(ws), withAt: at.length ? distribution(at) : "not served with at", bytes: first.bytes };
      cold.push(first.ms);
      warm.push(...ws, ...at);
    }
    if (!cold.length) throw new Error(`no analytics query was served: ${JSON.stringify(rows).slice(0, 200)}`);
    const w = distribution(warm);
    put("api.cold.max", Math.round(Math.max(...cold)));
    put("api.warm.median", w.median);
    put("api.warm.p95", w.p95);
    return { queries: rows, warm: w, cursor };
  });
  await step("api comparison", async () => {
    const cursor = sink.steps["api latencies"]?.cursor ?? (await apiGet(observer, cookie, "/api/v1/analytics/metrics?ids=T1")).data?.cursor;
    // A comparison: the same figures for two groups at one cursor, requested together (as Compare does).
    const cmp = [];
    for (let i = 0; i < RUNS; i++) {
      const t = performance.now();
      const pair = await Promise.all(["risk=High", "risk=Low"].map((f) => apiGet(observer, cookie, `/api/v1/analytics/metrics?ids=T1,Q2,C1,K1,R1&${f}&at=${encodeURIComponent(cursor)}`)));
      const bad = pair.find((g) => g.status !== 200);
      if (bad) throw new Error(`the comparison query answered ${bad.status}: ${JSON.stringify(bad.body?.error ?? bad.body).slice(0, 160)}`);
      cmp.push(performance.now() - t);
    }
    put("api.compare.median", distribution(cmp).median);
    return { compare: distribution(cmp) };
  });
}

async function measureObserverLoad() {
  await step("observer idle", async () => {
    // Let the observer settle after the API step (checkpoint writes, caches) before sampling it.
    await sleep(15000);
    const r = { ...(await cpuOver(observer.pid, 20000)), loadAverage: os.loadavg().map((x) => Math.round(x * 10) / 10) };
    put("observer.idle.cpuPct", r.cpuPct);
    put("observer.idle.rssMB", r.rssMB);
    return r;
  });
  await step("observer while events are appended", async () => {
    const rate = Number(opt("append-rate", 200));
    const seconds = Number(opt("append-seconds", 15));
    const h0 = (await apiGet(observer, cookie, "/api/v1/health")).data?.freshness?.head;
    const appender = startAppender(subject.dir, { rate, duration: `${seconds}s` });
    const load = cpuOver(observer.pid, seconds * 1000);
    const lag = [];
    const until = Date.now() + seconds * 1000;
    while (Date.now() < until) {
      const t = performance.now();
      await apiGet(observer, cookie, "/api/v1/analytics/metrics?ids=T1,C1");
      lag.push(performance.now() - t);
      await sleep(250);
    }
    const r = await load;
    const done = await appender.done;
    let appended = null;
    try {
      appended = JSON.parse(done.out.slice(done.out.indexOf("{"))).events ?? null;
    } catch {
      appended = rate * seconds;
    }
    // Catch-up after the last append: how long until the projection has applied everything.
    const t = Date.now();
    await waitCaughtUp(observer, cookie, 120000);
    const caughtUpMs = Date.now() - t;
    const h1 = (await apiGet(observer, cookie, "/api/v1/health")).data?.freshness?.head;
    put("observer.append.cpuPct", r.cpuPct);
    put("observer.append.cpuMsPerEvent", appended ? Math.round((r.cpuMs / appended) * 1000) / 1000 : null);
    put("observer.append.lagMs", caughtUpMs);
    return { ...r, appended, rate, seconds, headBefore: h0, headAfter: h1, caughtUpAfterMs: caughtUpMs, queryWhileAppending: distribution(lag) };
  });
}

// ------------------------------------------------------------ the browser

let browser;

async function openPage(area = "pulse") {
  const context = await browser.newContext({ viewport: { width: 1512, height: 982 }, colorScheme: "dark" });
  const page = await context.newPage();
  const cdp = await context.newCDPSession(page);
  await cdp.send("Performance.enable");
  const url = MODE === "proof" ? `${DEV_ORIGIN}/src/analytics/dev/proof.html?theme=dark&window=all&area=${area}` : `${DEV_ORIGIN}/#analytics?area=${area}`;
  if (MODE === "live") {
    observer.target();
    await page.goto(observer.link(), { waitUntil: "load" });
  }
  await page.addInitScript(() => {
    const w = window;
    const look = () => {
      const main = [...document.querySelectorAll("main[aria-label]")].pop();
      const ready = document.querySelector("[data-analytics-ready]") || (main && main.querySelector("figure, [data-readout]"));
      const placeholder = /is not connected to this source yet/.test(document.querySelector("[data-analytics-workspace]")?.textContent ?? "");
      if (ready || placeholder) w.__anReady = performance.now();
      else requestAnimationFrame(look);
    };
    requestAnimationFrame(look);
  });
  await page.goto(url, { waitUntil: "load" });
  await page.waitForFunction(() => window.__anReady !== undefined, undefined, { timeout: 60000 });
  if (MODE === "live" && /is not connected to this source yet/.test(await page.locator("[data-analytics-workspace]").innerText())) {
    await context.close();
    throw new Error("the Shell mounts the placeholder for a live source (the live provider is not wired yet)");
  }
  return { context, page, cdp };
}

/**
 * Time from an action done in the page to the last DOM change it caused (quiet for `quietMs`), and to
 * `data-analytics-ready` when the build sets it. `action` runs in the page and returns nothing.
 */
async function timed(page, action, arg) {
  return page.evaluate(
    async ({ action, arg }) => {
      const root = document.querySelector("[data-analytics-workspace], .an-root") ?? document.body;
      let last = performance.now();
      const mo = new MutationObserver(() => (last = performance.now()));
      mo.observe(root, { subtree: true, childList: true, characterData: true, attributes: true });
      const t0 = performance.now();
      new Function("arg", action)(arg);
      await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
      const quietMs = 150;
      while (performance.now() - last < quietMs && performance.now() - t0 < 30000) await new Promise((r) => setTimeout(r, 25));
      mo.disconnect();
      return Math.round((last - t0) * 10) / 10;
    },
    { action, arg },
  );
}

/** As `timed`, for an action Playwright performs (a key, a drag's release): the clock starts in the page just before it; null if nothing changed. */
async function timedBy(page, act) {
  await page.evaluate(() => {
    const root = document.querySelector("[data-analytics-workspace], .an-root") ?? document.body;
    window.__kq = { t0: 0, last: 0 };
    window.__kmo?.disconnect();
    window.__kmo = new MutationObserver(() => (window.__kq.last = performance.now()));
    window.__kmo.observe(root, { subtree: true, childList: true, characterData: true, attributes: true });
    window.__kq.t0 = performance.now();
  });
  await act();
  return page.evaluate(async () => {
    const q = window.__kq;
    await new Promise((r) => setTimeout(r, 200));
    while (q.last && performance.now() - q.last < 150 && performance.now() - q.t0 < 30000) await new Promise((r) => setTimeout(r, 25));
    window.__kmo.disconnect();
    return q.last ? Math.round((q.last - q.t0) * 10) / 10 : null;
  });
}

const CLICK_AREA = "const b=[...document.querySelectorAll(\"nav[aria-label='Analytics areas'] button\")].find(x=>x.textContent.trim().startsWith(arg)); b.click();";
// The window presets by position (the last is the whole history, whatever its label): 0 = 7 days, 2 = 28 days, -1 = all.
const CLICK_RADIO = "const r=[...document.querySelectorAll('[role=radiogroup][aria-label=\"Time window\"] [role=radio], [role=radiogroup][aria-label=\"Period\"] [role=radio]')]; r.at(arg).click();";
const SET_SELECT = "const l=[...document.querySelectorAll('label')].find(x=>x.firstChild&&x.firstChild.textContent.trim()===arg.label); const s=l?l.querySelector('select'):document.querySelector('select[aria-label=\"'+arg.label+'\"]'); s.value=arg.value; s.dispatchEvent(new Event('change',{bubbles:true}));";

async function measureUi() {
  await step("ui initial render", async () => {
    const runs = [];
    for (let i = 0; i < Math.min(RUNS, 5); i++) {
      const { context, page } = await openPage("pulse");
      runs.push(Math.round(await page.evaluate(() => window.__anReady)));
      await context.close();
    }
    put("ui.initial.median", distribution(runs).median);
    return { navToFirstFigureMs: distribution(runs), runs };
  });
  await step("ui area switch, window, filter, compare, hover, heap", async () => {
    const { context, page, cdp } = await openPage("pulse");
    const heap0 = await heapAfterGc(cdp);
    const areas = {};
    for (let round = 0; round < 3; round++)
      for (const a of AREAS) (areas[a.id] ??= []).push(await timed(page, CLICK_AREA, a.label));
    const allArea = Object.values(areas).flat();
    await timed(page, CLICK_AREA, "Factory Pulse");
    const win = [];
    for (let i = 0; i < 3; i++) for (const w of [0, 2, -1]) win.push(await timed(page, CLICK_RADIO, w));
    const filter = [];
    for (let i = 0; i < 3; i++) for (const value of ["high", "low", ""]) filter.push(await timed(page, SET_SELECT, { label: "Risk", value }));
    const compare = [];
    for (let i = 0; i < 3; i++) {
      await timed(page, CLICK_AREA, "Factory Pulse");
      compare.push(await timed(page, CLICK_AREA, "Compare"));
    }
    // Hover: pointer onto a mark until its tip is in the page.
    await timed(page, CLICK_AREA, "Factory Pulse");
    const marks = page.locator("main[aria-label] figure svg [role=img], main[aria-label] figure svg [role=button]");
    const hover = [];
    const n = Math.min(await marks.count(), 15);
    for (let i = 0; i < n; i++) {
      const box = await marks.nth(i).boundingBox();
      if (!box) continue;
      await page.mouse.move(box.x - 30, box.y - 30);
      await page.evaluate(() => (window.__hv = performance.now()));
      await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
      const ms = await page.evaluate(
        () =>
          new Promise((done) => {
            const t = window.__hv;
            const look = () => (document.querySelector(".an-tip, [role=tooltip], [data-analytics-tip]") ? done(performance.now() - t) : performance.now() - t > 2000 ? done(null) : requestAnimationFrame(look));
            look();
          }),
      );
      if (ms !== null) hover.push(Math.round(ms * 10) / 10);
    }
    // Brush, when there is one: a drag across a third of its chart, timed from the release.
    let brush = "not measurable yet: no [data-analytics-brush] in the workspace";
    await timed(page, CLICK_AREA, "Factory Pulse");
    const area = page.locator("[data-analytics-brush]").first();
    if (await area.count()) {
      const ts = [];
      for (let i = 0; i < 4; i++) {
        const b = await area.boundingBox();
        const y = b.y + b.height / 2;
        await page.mouse.move(b.x + b.width * (0.2 + i * 0.05), y);
        await page.mouse.down();
        await page.mouse.move(b.x + b.width * (0.5 + i * 0.05), y, { steps: 6 });
        ts.push(await timedBy(page, () => page.mouse.up()));
        const undo = page.locator("[data-analytics-chip-window] button").first();
        if (await undo.count()) await undo.click();
        await sleep(300);
      }
      const moved = ts.filter((x) => x !== null);
      brush = moved.length ? distribution(moved) : "not measurable yet: a drag across the brush changed nothing";
      if (moved.length) put("ui.brush.median", brush.median);
    }
    const heap1 = await heapAfterGc(cdp);
    await context.close();
    put("ui.area.median", distribution(allArea).median);
    put("ui.window.median", distribution(win).median);
    put("ui.filter.median", distribution(filter).median);
    put("ui.compare.median", distribution(compare).median);
    if (hover.length) put("ui.hover.median", distribution(hover).median);
    put("ui.heapDeltaMB", Math.round((heap1.heapMB - heap0.heapMB) * 10) / 10);
    return {
      areaSwitch: Object.fromEntries(Object.entries(areas).map(([k, v]) => [k, distribution(v)])),
      areaAll: distribution(allArea),
      window: distribution(win),
      filter: distribution(filter),
      compare: distribution(compare),
      hover: hover.length ? distribution(hover) : "not measurable yet: no tip appeared on hovering a named mark",
      brush,
      heap: { before: heap0, after: heap1 },
    };
  });
}

// ------------------------------------------------------------ run

try {
  if (MODE === "live") {
    await liveSetup();
    await measureRebuild();
    if (observer) {
      await measureApi();
      await measureObserverLoad();
    }
  } else await ensureStack();
  browser = await chromium.launch({ headless: !argv.includes("--headed") });
  if (MODE === "proof" || observer) await measureUi();
  if (MODE === "live" && report.baseline) {
    // The same observer steps, with the baseline binary on its own copy. No UI: the baseline has no Analytics workspace.
    await browser.close();
    browser = null;
    await observer?.stop();
    observer = null;
    sink = report.baseline;
    subject = { binary: report.baseline.binary, dir: report.baseline.dir };
    await measureRebuild();
    if (observer) {
      await measureApi();
      await measureObserverLoad();
    }
    sink = report;
  }
} finally {
  await browser?.close();
  await observer?.stop();
  stopOwn();
}

report.machine.loadAverageAtEnd = os.loadavg().map((x) => Math.round(x * 10) / 10);
const file = join(out, `analytics-measure-${MODE}.json`);
writeFileSync(file, JSON.stringify(report, null, 2));
console.log(`\nAnalytics measurement, mode ${MODE}${report.workload ? `, ${report.workload.project} (${report.workload.events ?? "?"} events)` : ""}\n`);
const verdict = (v, b) => (v === undefined || v === null ? "not measured" : v <= b ? "pass" : "fail");
if (report.baseline) {
  console.log(`Baseline: ${report.baseline.binary}\n`);
  console.log("| Measure | Working tree | Result | Baseline | Result | Budget |\n|---|---|---|---|---|---|");
  for (const [k, b] of Object.entries(BUDGET)) {
    const v = report.results[k];
    const w = k.startsWith("ui.") ? undefined : report.baseline.results[k];
    console.log(`| ${k} | ${v ?? "-"} | ${verdict(v, b)} | ${w ?? "-"} | ${k.startsWith("ui.") ? "no UI" : verdict(w, b)} | ${b} |`);
  }
} else {
  console.log("| Measure | Value | Budget | Result |\n|---|---|---|---|");
  for (const [k, b] of Object.entries(BUDGET)) console.log(`| ${k} | ${report.results[k] ?? "-"} | ${b} | ${verdict(report.results[k], b)} |`);
}
for (const [label, r] of [["", report], [" (baseline)", report.baseline]]) {
  const missing = Object.entries(r?.steps ?? {}).filter(([, s]) => !s.ok);
  if (missing.length) console.log(`\nNot measurable yet${label}:\n${missing.map(([k, s]) => `- ${k}: ${s.notMeasurable}`).join("\n")}`);
}
if (report.baseline) {
  const q = (r) => r?.steps?.["api latencies"]?.queries ?? {};
  console.log("\n| Query (warm median ms) | Working tree | Baseline |\n|---|---|---|");
  for (const name of new Set([...Object.keys(q(report)), ...Object.keys(q(report.baseline))])) {
    const cell = (x) => (!x ? "-" : x.notServed ? `not served (${x.notServed.slice(0, 40)})` : x.warm.median);
    console.log(`| ${name} | ${cell(q(report)[name])} | ${cell(q(report.baseline)[name])} |`);
  }
}
console.log(`\nReport: ${file}`);
